-- entity_spec から導出される CHECK。同じ式なら置き換えても差分にならない。
do $$
begin
    if not exists (
        select 1 from pg_constraint c
        where c.conrelid = 'public.loans'::regclass and c.conname = 'loans_state_enum'
          and pg_get_constraintdef(c.oid) = 'CHECK ((state = ANY (ARRAY[''requested''::text, ''checked_out''::text, ''overdue''::text, ''returned''::text])))'
    ) then
        alter table public.loans drop constraint if exists loans_state_enum;
        alter table public.loans add constraint loans_state_enum check (state = ANY (ARRAY['requested'::text, 'checked_out'::text, 'overdue'::text, 'returned'::text]));
    end if;
end
$$;

-- 外部キー。**両側の表のファイルに出す** —— 両方の表が在って、その列にまだ外部キーが無いときだけ張るので、先に当たった側は通り過ぎ、後から当たった側で張られる(相互参照する 2 表でも当たる)。既にある(名前が違っていても同じ列の)ものには触れない。
